CREATE TABLE menus (id varchar(64) PRIMARY KEY,parent_id varchar(64) NULL,menu_key varchar(255) NOT NULL,name text NOT NULL,menu_type varchar(32) NOT NULL,route_path text NOT NULL,component text NOT NULL,external_url text NOT NULL,icon text NOT NULL,permission_id varchar(64) NULL,visible boolean NOT NULL DEFAULT true,status varchar(32) NOT NULL,sort_order bigint NOT NULL DEFAULT 0,metadata json NOT NULL,created_at timestamp(6) NOT NULL,created_by text NOT NULL,updated_at timestamp(6) NOT NULL,updated_by text NOT NULL,version bigint NOT NULL,deleted_at timestamp(6) NULL,deleted_by text,UNIQUE KEY menus_key_unique(menu_key),KEY menus_parent_idx(parent_id,sort_order),KEY menus_permission_idx(permission_id));
